insert into public.decision_library (category, title, area, milestone_key, lead_weeks, why, sort_order) values
  ('Bath layout', 'Tub, shower or both', 'bath', 'rough_in', 2, 'This sets where the drains and walls go; every other bathroom choice follows from it.', 63),
