  ('Plumbing fixtures', 'Tub filler and faucet', 'bath', 'rough_in', 4, 'Wall- or floor-mounted fillers need their pipes placed at rough-in.', 68),
  ('Plumbing fixtures', 'Vanity faucets', 'bath', 'rough_in', 4, 'Wall-mounted faucets need pipes in the wall; deck faucets set the sink holes.', 69),
  ('Plumbing fixtures', 'Plumbing fixture finish (chrome, nickel, black, brass)', 'bath', 'rough_in', 4, 'Valves, faucets and drains should match, and some finishes take longer to ship.', 70),
  ('Plumbing fixtures', 'Bidet seat or bidet (yes/no)', 'bath', 'rough_in', 2, 'A bidet seat needs an outlet beside the toilet.', 71),
