  ('Framing', 'Mirror or medicine cabinet (recessed or on the wall)', 'bath', 'drywall', 3, 'A recessed cabinet needs an opening framed before drywall.', 78),
  ('Tile', 'Shower floor tile', 'bath', 'finish', 6, 'Small tiles or pebbles grip better and follow the slope to the drain.', 79),
  ('Tile', 'Accent and niche tile', 'bath', 'finish', 6, 'Ordered with the main tile so it arrives together.', 80),
  ('Tile', 'How high the wall tile goes', 'bath', 'finish', 2, 'Half wall, full height or to the ceiling changes how much tile to order.', 81),
