  ('Kitchen layout', 'Island size and seating', 'kitchen', 'rough_in', 2, 'Plumbing, power and floor outlets in an island are set at rough-in.', 88),
  ('Kitchen layout', 'Range fuel (gas, electric or induction)', 'kitchen', 'rough_in', 4, 'Gas needs a gas line; electric and induction need a large circuit.', 89),
